window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["composio"]={html:"<div class=\"own-composio\">\n  <!-- ── NAV ─────────────────────────────────────────────────────────────── -->\n  <header class=\"cp-nav\" id=\"cpNav\">\n    <a class=\"cp-wordmark\" href=\"#cp-top\" aria-label=\"Northwind home\"><span class=\"cp-mark\" aria-hidden=\"true\"></span>Northwind</a>\n    <nav class=\"cp-menu\" aria-label=\"Primary\">\n      <a href=\"#cp-hero\">Product</a>\n      <a href=\"#cp-toolkits\">Toolkits</a>\n      <a href=\"#cp-code\">Docs</a>\n      <a href=\"#cp-pricing\">Pricing</a>\n      <a href=\"#cp-customers\">Customers</a>\n    </nav>\n    <div class=\"cp-nav-right\">\n      <span class=\"cp-stars\" aria-label=\"GitHub stars\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3.2l2.6 5.3 5.8.8-4.2 4.1 1 5.8L12 16.5 6.8 19.2l1-5.8L3.6 9.3l5.8-.8z\" fill=\"currentColor\"/></svg>4.2k</span>\n      <a class=\"cp-nav-link\" href=\"#\">Sign in</a>\n      <a class=\"cp-btn cp-btn-primary\" href=\"#cp-pricing\">Get started</a>\n      <button class=\"cp-burger\" type=\"button\" id=\"cpBurger\" aria-label=\"Open menu\" aria-expanded=\"false\"><span></span><span></span><span></span></button>\n    </div>\n  </header>\n\n  <main id=\"cp-top\">\n    <!-- ── HERO with spotlight glow + 2x2 terminal grid ───────────────────── -->\n    <section id=\"cp-hero\" class=\"cp-hero\" aria-labelledby=\"cpHeroH\">\n      <div class=\"cp-glow\" aria-hidden=\"true\"></div>\n      <div class=\"cp-hero-copy\">\n        <span class=\"cp-badge\">Now in general availability</span>\n        <h1 id=\"cpHeroH\" class=\"cp-hero-title\">Give your ops agents<br>every tool they need</h1>\n        <p class=\"cp-hero-sub\">Northwind connects your agents to the systems of record, then reconciles what they return. One integration layer for the whole operation.</p>\n        <div class=\"cp-hero-cta\">\n          <a class=\"cp-btn cp-btn-primary cp-btn-lg\" href=\"#cp-pricing\">Start building</a>\n          <a class=\"cp-btn cp-btn-outline\" href=\"#cp-code\">Read the docs</a>\n        </div>\n      </div>\n\n      <div class=\"cp-terminal\" aria-label=\"Northwind terminal mockup\">\n        <div class=\"cp-terminal-bar\">\n          <span class=\"cp-dot\"></span><span class=\"cp-dot\"></span><span class=\"cp-dot\"></span>\n          <span class=\"cp-terminal-name\">northwind &mdash; ops-reconciler</span>\n        </div>\n        <div class=\"cp-grid\">\n          <div class=\"cp-pane\">\n            <span class=\"cp-pane-h\">$ nw tools list</span>\n            <span class=\"cp-code\"><b class=\"cp-c-blue\">dataverse</b> query_records</span>\n            <span class=\"cp-code\"><b class=\"cp-c-cyan\">snowflake</b> run_sql</span>\n            <span class=\"cp-code\"><b class=\"cp-c-violet\">sap</b> read_orders</span>\n          </div>\n          <div class=\"cp-pane\">\n            <span class=\"cp-pane-h\">$ nw run reconcile</span>\n            <span class=\"cp-code cp-out\">&#10003; 14 lines scanned</span>\n            <span class=\"cp-code cp-out\">&#10003; 3 anomalies flagged</span>\n            <span class=\"cp-code cp-out cp-c-green\">&#10003; done in 1.8s</span>\n          </div>\n          <div class=\"cp-pane\">\n            <span class=\"cp-pane-h\">output / week-41.json</span>\n            <span class=\"cp-code\">{</span>\n            <span class=\"cp-code\">&nbsp;&nbsp;\"yield\": <b class=\"cp-c-cyan\">94.6</b>,</span>\n            <span class=\"cp-code\">&nbsp;&nbsp;\"lines\": <b class=\"cp-c-cyan\">14</b></span>\n            <span class=\"cp-code\">}</span>\n          </div>\n          <div class=\"cp-pane\">\n            <span class=\"cp-pane-h\">agent / digest-writer</span>\n            <span class=\"cp-code\">&gt; summarise for the night shift</span>\n            <span class=\"cp-code cp-c-dim\">Busan flagged on 3 lines...</span>\n            <span class=\"cp-code cp-c-dim\">draft ready &#8594; send</span>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── TOOLKITS ────────────────────────────────────────────────────────── -->\n    <section id=\"cp-toolkits\" class=\"cp-toolkits\" aria-labelledby=\"cpToolkitsH\">\n      <div class=\"cp-sec-head\">\n        <span class=\"cp-eyebrow\">Toolkits</span>\n        <h2 id=\"cpToolkitsH\" class=\"cp-h2\">400+ tools, one contract</h2>\n        <p class=\"cp-lead\">Connect the systems your operation already runs on &mdash; no bespoke adapters.</p>\n      </div>\n      <div class=\"cp-toolkit-grid\" id=\"cpToolkitGrid\"></div>\n    </section>\n\n    <!-- ── FEATURE CARDS ────────────────────────────────────────────────────── -->\n    <section class=\"cp-features\" aria-labelledby=\"cpFeaturesH\">\n      <div class=\"cp-feature-grid\">\n        <article class=\"cp-feature\">\n          <span class=\"cp-feature-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 7h16M4 12h16M4 17h16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg></span>\n          <h3>One integration layer</h3>\n          <p>Authenticate once. Every agent gets the scoped tools it needs, nothing more.</p>\n        </article>\n        <article class=\"cp-feature\">\n          <span class=\"cp-feature-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 3v6M12 15v6M3 12h6M15 12h6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/><circle cx=\"12\" cy=\"12\" r=\"3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/></svg></span>\n          <h3>Deterministic runs</h3>\n          <p>Replayable traces for every agent action. Same input, same reconciliation.</p>\n        </article>\n        <article class=\"cp-feature\">\n          <span class=\"cp-feature-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M5 12l4.5 4.5L19 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></span>\n          <h3>Audit by default</h3>\n          <p>Every tool call signed and logged. The lineage your audit desk asks for.</p>\n        </article>\n      </div>\n    </section>\n\n    <!-- ── CODE ──────────────────────────────────────────────────────────────── -->\n    <section id=\"cp-code\" class=\"cp-code-sec\" aria-labelledby=\"cpCodeH\">\n      <div class=\"cp-code-copy\">\n        <span class=\"cp-eyebrow\">For developers</span>\n        <h2 id=\"cpCodeH\" class=\"cp-h2\">Ship in an afternoon</h2>\n        <p class=\"cp-lead\">A typed SDK, a CLI, and a hosted runner. Point it at Northwind and your agents reconcile.</p>\n        <ul class=\"cp-code-list\">\n          <li><b>TypeScript &amp; Python</b> SDKs, fully typed</li>\n          <li><b>Northwind CLI</b> for local runs and replays</li>\n          <li><b>Webhooks</b> when a digest lands</li>\n        </ul>\n      </div>\n      <div class=\"cp-code-block\" role=\"group\" aria-label=\"Code example\">\n        <div class=\"cp-code-bar\"><span>reconcile.ts</span><button class=\"cp-copy\" type=\"button\" id=\"cpCopy\">Copy</button></div>\n        <pre class=\"cp-pre\"><code id=\"cpCode\"><span class=\"cp-k\">import</span> { Northwind } <span class=\"cp-k\">from</span> <span class=\"cp-s\">\"@northwind/sdk\"</span>;\n\n<span class=\"cp-k\">const</span> nw = <span class=\"cp-k\">new</span> Northwind({ region: <span class=\"cp-s\">\"luzon\"</span> });\n\n<span class=\"cp-k\">const</span> report = <span class=\"cp-k\">await</span> nw.agents.reconcile({\n  lines: <span class=\"cp-s\">\"all\"</span>,\n  week: <span class=\"cp-n\">41</span>,\n});\n\n<span class=\"cp-c\">// 14 lines scanned, flagged where yield drifted</span>\nconsole.log(report.flagged);</code></pre>\n      </div>\n    </section>\n\n    <!-- ── SPOTLIGHT CTA ─────────────────────────────────────────────────────── -->\n    <section id=\"cp-customers\" class=\"cp-spot\" aria-labelledby=\"cpSpotH\">\n      <div class=\"cp-spot-glow\" aria-hidden=\"true\"></div>\n      <blockquote class=\"cp-quote\">\n        <p>&ldquo;We replaced three reconciliation spreadsheets and a nightly batch with one Northwind board. The night shift sees the same number the analysts do.&rdquo;</p>\n        <footer class=\"cp-quote-by\"><span class=\"cp-quote-av\" aria-hidden=\"true\">RM</span><span><b>Rhea Mercado</b> · Head of Operations, Caldera</span></footer>\n      </blockquote>\n      <div class=\"cp-spot-cta\">\n        <h2 id=\"cpSpotH\" class=\"cp-spot-title\">Reconcile your first week for free</h2>\n        <a class=\"cp-btn cp-btn-primary cp-btn-lg\" href=\"#cp-pricing\">Get started</a>\n      </div>\n    </section>\n\n    <!-- ── PRICING ──────────────────────────────────────────────────────────── -->\n    <section id=\"cp-pricing\" class=\"cp-pricing\" aria-labelledby=\"cpPricingH\">\n      <div class=\"cp-sec-head\">\n        <span class=\"cp-eyebrow\">Pricing</span>\n        <h2 id=\"cpPricingH\" class=\"cp-h2\">Start free. Scale per region.</h2>\n        <p class=\"cp-lead\">No card required. Add regions as the operation grows.</p>\n      </div>\n      <div class=\"cp-tier-grid\">\n        <article class=\"cp-tier\">\n          <span class=\"cp-tier-name\">Hobby</span>\n          <span class=\"cp-tier-price\">$0<span>/mo</span></span>\n          <ul><li>1 region</li><li>5k agent calls</li><li>Community support</li></ul>\n          <a class=\"cp-btn cp-btn-secondary\" href=\"#\">Start free</a>\n        </article>\n        <article class=\"cp-tier cp-tier-featured\">\n          <span class=\"cp-tier-name\">Team</span>\n          <span class=\"cp-tier-price\">$390<span>/mo</span></span>\n          <ul><li>Up to 6 regions</li><li>1M agent calls</li><li>Reconciliation engine</li></ul>\n          <a class=\"cp-btn cp-btn-primary\" href=\"#\">Start building</a>\n        </article>\n        <article class=\"cp-tier\">\n          <span class=\"cp-tier-name\">Enterprise</span>\n          <span class=\"cp-tier-price\">Custom</span>\n          <ul><li>Unlimited regions</li><li>SSO &amp; audit</li><li>Dedicated support</li></ul>\n          <a class=\"cp-btn cp-btn-secondary\" href=\"#\">Talk to us</a>\n        </article>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── FOOTER ───────────────────────────────────────────────────────────── -->\n  <footer class=\"cp-foot\">\n    <div class=\"cp-foot-top\">\n      <a class=\"cp-wordmark\" href=\"#cp-top\"><span class=\"cp-mark\" aria-hidden=\"true\"></span>Northwind</a>\n      <p class=\"cp-foot-note\">Operations analytics for teams that need the numbers to agree.</p>\n    </div>\n    <div class=\"cp-foot-cols\">\n      <div class=\"cp-foot-col\"><h3>Product</h3><a href=\"#\">Toolkits</a><a href=\"#\">Agents</a><a href=\"#\">Reconciliation</a><a href=\"#\">Integrations</a></div>\n      <div class=\"cp-foot-col\"><h3>Developers</h3><a href=\"#\">Docs</a><a href=\"#\">CLI</a><a href=\"#\">API</a><a href=\"#\">Status</a></div>\n      <div class=\"cp-foot-col\"><h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Blog</a><a href=\"#\">Contact</a></div>\n      <div class=\"cp-foot-col\"><h3>Legal</h3><a href=\"#\">Privacy</a><a href=\"#\">Terms</a><a href=\"#\">Security</a><a href=\"#\">DPA</a></div>\n    </div>\n    <div class=\"cp-legal\">\n      <span>&copy; 2026 Northwind Analytics — a fictional product. Sample data, showcase only.</span>\n      <span class=\"cp-status\"><i aria-hidden=\"true\"></i>All systems normal</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — in Composio's design language, for showcase.html ═══════════\n   Monolithic dark canvas (#0f0f0f) top to bottom, one voltage of deep electric\n   blue (#0007cd), a single sans family (abcDiatype -> Inter) with JetBrains Mono\n   on every code surface, and a 2x2 terminal mockup grid behind a radial blue\n   spotlight as the hero anchor. Depth is brightness-step elevation, not shadows.\n   Compact developer-ergonomic radii: 8px CTAs, 12-16px cards. */\n\n.own-composio {\n  --primary: #0007cd;\n  --primary-active: #0005a3;\n  --primary-glow: #1a26ff;\n  --ink: #ffffff;\n  --body: #a8a8a8;\n  --body-strong: #ffffff;\n  --muted: #888888;\n  --muted-soft: #666666;\n  --hairline: #222222;\n  --hairline-soft: #1a1a1a;\n  --hairline-strong: #333333;\n  --canvas: #0f0f0f;\n  --canvas-deep: #000000;\n  --surface-card: #181818;\n  --surface-card-elevated: #222222;\n  --surface-strong: #2a2a2a;\n  --on-primary: #ffffff;\n  --accent-cyan: #00d4ff;\n  --accent-violet: #7b3aed;\n  --semantic-success: #33d17a;\n  --semantic-error: #ff4d4d;\n\n  --font-sans: 'abcDiatype', 'Inter', ui-sans-serif, system-ui, sans-serif;\n  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;\n\n  --r-xs: 4px;\n  --r-sm: 6px;\n  --r-md: 8px;\n  --r-lg: 12px;\n  --r-xl: 16px;\n  --r-pill: 9999px;\n\n  --gut: clamp(20px, 5cqi, 64px);\n  --section: clamp(56px, 8cqi, 96px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--canvas);\n  color: var(--body-strong);\n  font-family: var(--font-sans);\n  font-size: 16px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n  overflow-x: clip;\n}\n.own-composio *, .own-composio *::before, .own-composio *::after { box-sizing: border-box; }\n.own-composio a { color: inherit; text-decoration: none; }\n.own-composio button { font: inherit; cursor: pointer; }\n.own-composio :focus-visible { outline: 3px solid var(--primary-glow); outline-offset: 2px; border-radius: 6px; }\n\n/* ── nav ───────────────────────────────────────────────────────────────────── */\n.own-composio .cp-nav { position: sticky; top: 68px; z-index: 40; display: flex; align-items: center; gap: 24px; height: 64px; padding: 0 var(--gut); background: rgba(15, 15, 15, .88); border-bottom: 1px solid var(--hairline); backdrop-filter: saturate(160%) blur(12px); -webkit-backdrop-filter: saturate(160%) blur(12px); }\n.own-composio .cp-wordmark { display: inline-flex; align-items: center; gap: 10px; font-size: 18px; font-weight: 600; letter-spacing: -0.3px; color: var(--ink); }\n.own-composio .cp-mark { width: 18px; height: 18px; border-radius: 5px; background: linear-gradient(135deg, var(--primary-glow), var(--primary)); }\n.own-composio .cp-menu { display: flex; gap: 26px; margin: 0 auto; font-size: 14px; font-weight: 500; color: var(--body); }\n.own-composio .cp-menu a:hover { color: var(--ink); }\n.own-composio .cp-nav-right { display: flex; align-items: center; gap: 14px; margin-left: auto; }\n.own-composio .cp-stars { display: inline-flex; align-items: center; gap: 6px; font-family: var(--font-mono); font-size: 12px; color: var(--body); }\n.own-composio .cp-stars svg { width: 14px; height: 14px; color: #f5c451; }\n.own-composio .cp-nav-link { font-size: 14px; font-weight: 500; color: var(--body); }\n.own-composio .cp-nav-link:hover { color: var(--ink); }\n.own-composio .cp-burger { display: none; flex-direction: column; gap: 4px; width: 40px; height: 40px; align-items: center; justify-content: center; border: 1px solid var(--hairline-strong); border-radius: var(--r-md); background: var(--surface-card); }\n.own-composio .cp-burger span { display: block; width: 18px; height: 2px; background: var(--body-strong); }\n\n/* ── buttons ──────────────────────────────────────────────────────────────── */\n.own-composio .cp-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 40px; padding: 0 18px; border: 1px solid transparent; border-radius: var(--r-md); font-family: var(--font-sans); font-size: 14px; font-weight: 500; line-height: 1; transition: background-color .18s, border-color .18s; }\n.own-composio .cp-btn-lg { height: 48px; padding: 0 24px; font-size: 15px; }\n.own-composio .cp-btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-composio .cp-btn-primary:hover { background: var(--primary-active); }\n.own-composio .cp-btn-secondary { background: var(--surface-card-elevated); color: var(--body-strong); }\n.own-composio .cp-btn-secondary:hover { background: var(--surface-strong); }\n.own-composio .cp-btn-outline { background: transparent; color: var(--body-strong); border-color: var(--hairline-strong); }\n.own-composio .cp-btn-outline:hover { border-color: var(--body); }\n\n.own-composio .cp-badge { display: inline-block; padding: 4px 10px; border-radius: var(--r-pill); background: var(--surface-card-elevated); color: var(--body-strong); font-size: 11px; font-weight: 600; letter-spacing: .88px; text-transform: uppercase; }\n.own-composio .cp-eyebrow { display: inline-block; margin-bottom: 14px; font-size: 11px; font-weight: 600; letter-spacing: .88px; text-transform: uppercase; color: var(--muted); }\n.own-composio .cp-h2 { font-size: clamp(30px, 4.4cqi, 44px); font-weight: 500; line-height: 1.1; letter-spacing: -1.32px; color: var(--ink); }\n.own-composio .cp-lead { margin-top: 14px; max-width: 52ch; font-size: 16px; line-height: 1.5; color: var(--body); }\n\n/* ── hero ──────────────────────────────────────────────────────────────────── */\n.own-composio .cp-hero { position: relative; padding: var(--section) var(--gut) clamp(40px, 6cqi, 72px); text-align: center; }\n.own-composio .cp-glow { position: absolute; left: 50%; top: 8%; transform: translateX(-50%); width: min(900px, 90cqi); height: 520px; pointer-events: none; background: radial-gradient(50% 50% at 50% 50%, rgba(26, 38, 255, .38) 0%, rgba(26, 38, 255, .12) 42%, transparent 72%); }\n.own-composio .cp-hero-copy { position: relative; z-index: 1; }\n.own-composio .cp-hero-title { font-size: clamp(40px, 7cqi, 72px); font-weight: 500; line-height: 1.05; letter-spacing: -2.16px; color: var(--ink); margin-top: 18px; }\n.own-composio .cp-hero-sub { margin: 20px auto 0; max-width: 58ch; font-size: 16px; line-height: 1.5; color: var(--body); }\n.own-composio .cp-hero-cta { display: flex; gap: 12px; flex-wrap: wrap; justify-content: center; margin-top: 28px; }\n\n/* ── terminal mockup (2x2) ─────────────────────────────────────────────────── */\n.own-composio .cp-terminal { position: relative; z-index: 1; margin: clamp(36px, 5cqi, 64px) auto 0; width: min(920px, 100%); border: 1px solid var(--hairline); border-radius: var(--r-xl); background: var(--canvas-deep); padding: 14px; text-align: left; box-shadow: 0 30px 80px -40px rgba(26, 38, 255, .55); }\n.own-composio .cp-terminal-bar { display: flex; align-items: center; gap: 7px; padding: 4px 6px 14px; }\n.own-composio .cp-dot { width: 10px; height: 10px; border-radius: 50%; background: #2e2e2e; }\n.own-composio .cp-dot:first-child { background: #ff5f57; }\n.own-composio .cp-dot:nth-child(2) { background: #febc2e; }\n.own-composio .cp-dot:nth-child(3) { background: #28c840; }\n.own-composio .cp-terminal-name { margin-left: 8px; font-family: var(--font-mono); font-size: 12px; color: var(--muted); }\n.own-composio .cp-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }\n.own-composio .cp-pane { display: grid; gap: 6px; align-content: start; min-height: 120px; padding: 20px; border-radius: var(--r-lg); background: var(--surface-card); border: 1px solid var(--hairline-soft); }\n.own-composio .cp-pane-h { font-family: var(--font-mono); font-size: 12px; color: var(--muted); margin-bottom: 6px; }\n.own-composio .cp-code { font-family: var(--font-mono); font-size: 13px; line-height: 1.5; color: var(--body); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.own-composio .cp-out { color: #cfcfcf; }\n.own-composio .cp-c-blue { color: #6f7bff; }\n.own-composio .cp-c-cyan { color: var(--accent-cyan); }\n.own-composio .cp-c-violet { color: #b28bff; }\n.own-composio .cp-c-green { color: var(--semantic-success); }\n.own-composio .cp-c-dim { color: var(--muted-soft); }\n\n/* ── toolkits ──────────────────────────────────────────────────────────────── */\n.own-composio .cp-toolkits { padding: var(--section) var(--gut); }\n.own-composio .cp-sec-head { text-align: center; max-width: 720px; margin: 0 auto clamp(32px, 5cqi, 56px); }\n.own-composio .cp-toolkit-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }\n.own-composio .cp-toolkit { display: grid; gap: 10px; align-content: start; padding: 20px; border-radius: var(--r-lg); background: var(--surface-card); border: 1px solid var(--hairline); }\n.own-composio .cp-toolkit-ico { display: grid; place-items: center; width: 40px; height: 40px; border-radius: var(--r-md); background: var(--surface-card-elevated); font-family: var(--font-mono); font-size: 13px; font-weight: 600; color: var(--body-strong); }\n.own-composio .cp-toolkit h3 { font-size: 16px; font-weight: 600; line-height: 1.4; }\n.own-composio .cp-toolkit p { font-size: 14px; line-height: 1.5; color: var(--body); }\n.own-composio .cp-toolkit-tag { font-family: var(--font-mono); font-size: 11px; color: var(--muted); }\n\n/* ── features ──────────────────────────────────────────────────────────────── */\n.own-composio .cp-features { padding: var(--section) var(--gut); }\n.own-composio .cp-feature-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-composio .cp-feature { padding: 28px; border-radius: var(--r-xl); background: var(--surface-card); border: 1px solid var(--hairline); }\n.own-composio .cp-feature-ico { display: grid; place-items: center; width: 44px; height: 44px; border-radius: var(--r-md); background: var(--surface-card-elevated); color: var(--accent-cyan); margin-bottom: 18px; }\n.own-composio .cp-feature-ico svg { width: 22px; height: 22px; }\n.own-composio .cp-feature h3 { font-size: 18px; font-weight: 600; line-height: 1.4; }\n.own-composio .cp-feature p { margin-top: 8px; font-size: 15px; line-height: 1.5; color: var(--body); }\n\n/* ── code section ──────────────────────────────────────────────────────────── */\n.own-composio .cp-code-sec { display: grid; grid-template-columns: 1fr 1.15fr; gap: clamp(28px, 4cqi, 56px); align-items: center; padding: var(--section) var(--gut); }\n.own-composio .cp-code-list { list-style: none; display: grid; gap: 12px; margin-top: 24px; }\n.own-composio .cp-code-list li { position: relative; padding-left: 24px; font-size: 15px; color: var(--body); }\n.own-composio .cp-code-list li::before { content: ''; position: absolute; left: 0; top: 7px; width: 11px; height: 6px; border-left: 2px solid var(--accent-cyan); border-bottom: 2px solid var(--accent-cyan); transform: rotate(-45deg); }\n.own-composio .cp-code-list b { color: var(--ink); font-weight: 600; }\n.own-composio .cp-code-block { border: 1px solid var(--hairline); border-radius: var(--r-lg); background: var(--canvas-deep); overflow: hidden; }\n.own-composio .cp-code-bar { display: flex; align-items: center; justify-content: space-between; padding: 12px 18px; border-bottom: 1px solid var(--hairline); font-family: var(--font-mono); font-size: 12px; color: var(--muted); }\n.own-composio .cp-copy { border: 1px solid var(--hairline-strong); border-radius: var(--r-sm); background: var(--surface-card); color: var(--body); font-family: var(--font-mono); font-size: 11px; padding: 4px 10px; }\n.own-composio .cp-copy:hover { color: var(--ink); border-color: var(--body); }\n.own-composio .cp-pre { margin: 0; padding: 20px; overflow-x: auto; font-family: var(--font-mono); font-size: 13px; line-height: 1.65; color: #d3d3d3; }\n.own-composio .cp-pre code { font: inherit; }\n.own-composio .cp-k { color: #b28bff; }\n.own-composio .cp-s { color: var(--accent-cyan); }\n.own-composio .cp-n { color: #f5c451; }\n.own-composio .cp-c { color: var(--muted); }\n\n/* ── spotlight CTA ──────────────────────────────────────────────────────────── */\n.own-composio .cp-spot { position: relative; margin: 0 var(--gut); padding: var(--section) clamp(24px, 4cqi, 64px); border-radius: var(--r-xl); background: var(--canvas-deep); border: 1px solid var(--hairline); overflow: hidden; text-align: center; }\n.own-composio .cp-spot-glow { position: absolute; left: 50%; bottom: -40%; transform: translateX(-50%); width: min(760px, 90cqi); height: 460px; pointer-events: none; background: radial-gradient(50% 50% at 50% 50%, rgba(26, 38, 255, .4) 0%, rgba(26, 38, 255, .1) 46%, transparent 72%); }\n.own-composio .cp-quote { position: relative; z-index: 1; margin: 0 auto; max-width: 760px; }\n.own-composio .cp-quote p { font-size: clamp(20px, 2.4cqi, 28px); font-weight: 500; line-height: 1.35; letter-spacing: -0.5px; color: var(--ink); }\n.own-composio .cp-quote-by { display: flex; align-items: center; justify-content: center; gap: 12px; margin-top: 24px; font-size: 14px; color: var(--body); }\n.own-composio .cp-quote-by b { color: var(--ink); font-weight: 600; }\n.own-composio .cp-quote-av { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 9999px; background: var(--surface-card-elevated); font-size: 13px; font-weight: 600; color: var(--body-strong); }\n.own-composio .cp-spot-cta { position: relative; z-index: 1; margin-top: clamp(36px, 5cqi, 56px); }\n.own-composio .cp-spot-title { font-size: clamp(28px, 3.6cqi, 44px); font-weight: 500; line-height: 1.1; letter-spacing: -1.32px; color: var(--ink); margin-bottom: 24px; }\n\n/* ── pricing ────────────────────────────────────────────────────────────────── */\n.own-composio .cp-pricing { padding: var(--section) var(--gut); }\n.own-composio .cp-tier-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; align-items: stretch; }\n.own-composio .cp-tier { display: grid; gap: 12px; align-content: start; padding: 28px; border: 1px solid var(--hairline); border-radius: var(--r-xl); background: var(--surface-card); }\n.own-composio .cp-tier-name { font-size: 13px; font-weight: 600; letter-spacing: .04em; text-transform: uppercase; color: var(--muted); }\n.own-composio .cp-tier-price { font-size: clamp(30px, 3.4cqi, 44px); font-weight: 500; line-height: 1.05; letter-spacing: -1.32px; color: var(--ink); }\n.own-composio .cp-tier-price span { font-size: 14px; font-weight: 400; color: var(--muted); letter-spacing: 0; }\n.own-composio .cp-tier ul { list-style: none; display: grid; gap: 10px; margin: 8px 0 12px; padding-top: 18px; border-top: 1px solid var(--hairline); font-size: 15px; color: var(--body); }\n.own-composio .cp-tier .cp-btn { width: 100%; }\n.own-composio .cp-tier-featured { border-color: var(--primary); box-shadow: 0 0 0 1px var(--primary), 0 30px 70px -40px rgba(26, 38, 255, .7); }\n\n/* ── footer ─────────────────────────────────────────────────────────────────── */\n.own-composio .cp-foot { padding: clamp(48px, 6cqi, 64px) var(--gut) 32px; border-top: 1px solid var(--hairline); }\n.own-composio .cp-foot-top { display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; padding-bottom: 32px; border-bottom: 1px solid var(--hairline); }\n.own-composio .cp-foot-note { font-size: 14px; color: var(--body); max-width: 44ch; }\n.own-composio .cp-foot-cols { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; padding: 40px 0; }\n.own-composio .cp-foot-col { display: grid; gap: 10px; align-content: start; }\n.own-composio .cp-foot-col h3 { font-size: 13px; font-weight: 600; color: var(--ink); margin-bottom: 4px; }\n.own-composio .cp-foot-col a { font-size: 14px; color: var(--body); }\n.own-composio .cp-foot-col a:hover { color: var(--ink); }\n.own-composio .cp-legal { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding-top: 22px; border-top: 1px solid var(--hairline); font-size: 13px; color: var(--muted); }\n.own-composio .cp-status { display: inline-flex; align-items: center; gap: 8px; color: var(--semantic-success); }\n.own-composio .cp-status i { width: 8px; height: 8px; border-radius: 50%; background: var(--semantic-success); box-shadow: 0 0 10px rgba(51, 209, 122, .8); }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-composio .cp-menu { display: none; }\n  .own-composio .cp-burger { display: flex; }\n  .own-composio .cp-toolkit-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-composio .cp-feature-grid { grid-template-columns: 1fr; }\n  .own-composio .cp-code-sec { grid-template-columns: 1fr; }\n  .own-composio .cp-tier-grid { grid-template-columns: 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-composio .cp-nav { top: 66px; height: 58px; gap: 10px; }\n  .own-composio .cp-stars { display: none; }\n  .own-composio .cp-grid { grid-template-columns: 1fr; }\n  .own-composio .cp-pane { min-height: 0; }\n  .own-composio .cp-foot-cols { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 430px) {\n  .own-composio .cp-toolkit-grid { grid-template-columns: 1fr; }\n  .own-composio .cp-hero-cta { flex-direction: column; align-items: stretch; }\n  .own-composio .cp-foot-cols { grid-template-columns: 1fr; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-composio *, .own-composio *::before, .own-composio *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — in Composio's design language, for showcase.html ════════════
   Registers window.OWN_LAYOUTS['composio'].init(root). Renders the toolkit grid
   from sample data and wires the code-block copy button. Returns a cleanup that
   detaches every listener and clears any pending timeout. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var TOOLKITS = [
    { ico: 'DV', name: 'Dataverse', tag: 'CRM', desc: 'Query and upsert records on any table.' },
    { ico: 'SF', name: 'Snowflake', tag: 'Warehouse', desc: 'Run governed SQL against the ops warehouse.' },
    { ico: 'SAP', name: 'SAP', tag: 'ERP', desc: 'Read orders, stock, and production confirmations.' },
    { ico: 'GH', name: 'GitHub', tag: 'Devtools', desc: 'Open issues and attach the reconciliation trace.' },
    { ico: 'SL', name: 'Slack', tag: 'Messaging', desc: 'Post the shift digest where the floor already is.' },
    { ico: 'NW', name: 'Northwind', tag: 'Internal', desc: 'Call the reconciliation engine directly.' },
    { ico: 'PG', name: 'Postgres', tag: 'Database', desc: 'Stream rows from operational stores.' },
    { ico: 'S3', name: 'Object store', tag: 'Storage', desc: 'Read and write export bundles.' }
  ];

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  OWN['composio'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var timeouts = [];
      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function later(fn, ms) { var id = window.setTimeout(fn, ms); timeouts.push(id); return id; }
      function $(s) { return root.querySelector(s); }

      var grid = $('#cpToolkitGrid');
      if (grid) {
        grid.innerHTML = TOOLKITS.map(function (t) {
          return '<article class="cp-toolkit">'
            + '<span class="cp-toolkit-ico" aria-hidden="true">' + esc(t.ico) + '</span>'
            + '<span class="cp-toolkit-tag">' + esc(t.tag) + '</span>'
            + '<h3>' + esc(t.name) + '</h3>'
            + '<p>' + esc(t.desc) + '</p>'
            + '</article>';
        }).join('');
      }

      var copy = $('#cpCopy');
      on(copy, 'click', function () {
        var code = $('#cpCode');
        var text = code ? code.textContent : '';
        function done() { if (copy) { copy.textContent = 'Copied'; later(function () { if (copy) copy.textContent = 'Copy'; }, 1400); } }
        try {
          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text).then(done, done);
          } else { done(); }
        } catch (e) { done(); }
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        timeouts.forEach(function (id) { clearTimeout(id); });
      };
    }
  };
})();
